[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>DeployCloud Blog — Discover the latest in web development</title>
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&display=swap" rel="stylesheet">
<link href="https://cdn.jsdelivr.net/npm/remixicon@4.6.0/fonts/remixicon.css" rel="stylesheet">
<style>
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --primary: #171717;
  --accent: #0072F5;
  --accent-hover: #0060D6;
  --bg: #FAFAFA;
  --bg-white: #FFFFFF;
  --border: #E5E5E5;
  --border-light: #F0F0F0;
  --text-primary: #171717;
  --text-secondary: #525252;
  --text-muted: #737373;
  --card-shadow: 0 1px 3px rgba(0,0,0,0.06), 0 1px 2px rgba(0,0,0,0.04);
  --card-shadow-hover: 0 10px 25px rgba(0,0,0,0.08), 0 4px 10px rgba(0,0,0,0.04);
  --radius: 12px;
  --radius-sm: 8px;
  --radius-pill: 9999px;
  --transition: 0.2s ease;
  --max-width: 1200px;
}

body {
  font-family: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
  background: var(--bg);
  color: var(--text-primary);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

a { text-decoration: none; color: inherit; }
button { border: none; cursor: pointer; font-family: inherit; }
img { max-width: 100%; display: block; }

.container { max-width: var(--max-width); margin: 0 auto; padding: 0 24px; }

/* ===== HEADER ===== */
.header {
  position: sticky;
  top: 0;
  z-index: 100;
  background: rgba(255,255,255,0.85);
  backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--border-light);
}

.header-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 64px;
}

.header-left { display: flex; align-items: center; gap: 32px; }

.logo {
  display: flex;
  align-items: center;
  gap: 8px;
  font-weight: 700;
  font-size: 18px;
  color: var(--primary);
}

.logo-icon {
  width: 28px;
  height: 28px;
  background: var(--primary);
  border-radius: 6px;
  display: flex;
  align-items: center;
  justify-content: center;
  color: white;
  font-size: 14px;
}

.nav-links { display: flex; align-items: center; gap: 4px; }

.nav-item {
  position: relative;
  display: flex;
  align-items: center;
  gap: 4px;
  padding: 8px 12px;
  font-size: 14px;
  font-weight: 500;
  color: var(--text-secondary);
  border-radius: var(--radius-sm);
  transition: all var(--transition);
  background: none;
}

.nav-item:hover, .nav-item.active {
  color: var(--text-primary);
  background: var(--border-light);
}

.nav-item i { font-size: 12px; transition: transform var(--transition); }
.nav-item.active i { transform: rotate(180deg); }

.header-right { display: flex; align-items: center; gap: 12px; }

.btn-ask-ai {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 7px 14px;
  font-size: 13px;
  font-weight: 500;
  color: var(--accent);
  background: rgba(0,114,245,0.08);
  border-radius: var(--radius-pill);
  transition: all var(--transition);
}

.btn-ask-ai:hover { background: rgba(0,114,245,0.14); }

.btn-login {
  padding: 7px 14px;
  font-size: 13px;
  font-weight: 500;
  color: var(--text-secondary);
  background: none;
  border-radius: var(--radius-pill);
  transition: all var(--transition);
}

.btn-login:hover { color: var(--text-primary); background: var(--border-light); }

.btn-signup {
  padding: 7px 16px;
  font-size: 13px;
  font-weight: 600;
  color: #fff;
  background: var(--primary);
  border-radius: var(--radius-pill);
  transition: all var(--transition);
}

.btn-signup:hover { background: #333; }

/* ===== MEGA MENU ===== */
.mega-menu {
  position: absolute;
  top: calc(100% + 8px);
  left: 50%;
  transform: translateX(-50%);
  background: var(--bg-white);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  box-shadow: 0 20px 60px rgba(0,0,0,0.12), 0 4px 20px rgba(0,0,0,0.06);
  padding: 24px;
  min-width: 640px;
  opacity: 0;
  visibility: hidden;
  transition: opacity 0.15s ease, visibility 0.15s ease;
  pointer-events: none;
}

.nav-item.active .mega-menu {
  opacity: 1;
  visibility: visible;
  pointer-events: auto;
}

.mega-menu-grid { display: grid; grid-template-columns: 1fr 1fr 1fr; gap: 24px; }
.mega-menu-col h4 {
  font-size: 11px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--text-muted);
  margin-bottom: 12px;
  padding-bottom: 8px;
  border-bottom: 1px solid var(--border-light);
}

.mega-menu-col a {
  display: flex;
  flex-direction: column;
  padding: 8px 10px;
  border-radius: var(--radius-sm);
  transition: background var(--transition);
}

.mega-menu-col a:hover { background: var(--border-light); }

.mega-menu-col .mm-title {
  font-size: 13px;
  font-weight: 600;
  color: var(--text-primary);
}

.mega-menu-col .mm-desc {
  font-size: 12px;
  color: var(--text-muted);
  line-height: 1.4;
  margin-top: 2px;
}

/* Resources dropdown */
.resources-menu {
  position: absolute;
  top: calc(100% + 8px);
  left: 50%;
  transform: translateX(-50%);
  background: var(--bg-white);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  box-shadow: 0 20px 60px rgba(0,0,0,0.12), 0 4px 20px rgba(0,0,0,0.06);
  padding: 24px;
  min-width: 480px;
  opacity: 0;
  visibility: hidden;
  transition: opacity 0.15s ease, visibility 0.15s ease;
  pointer-events: none;
}

.nav-item.active .resources-menu {
  opacity: 1;
  visibility: visible;
  pointer-events: auto;
}

.resources-grid { display: grid; grid-template-columns: 1fr 1fr 1fr; gap: 24px; }

.resources-grid h4 {
  font-size: 11px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--text-muted);
  margin-bottom: 10px;
  padding-bottom: 8px;
  border-bottom: 1px solid var(--border-light);
}

.resources-grid ul { list-style: none; }

.resources-grid li a {
  display: block;
  padding: 6px 10px;
  font-size: 13px;
  font-weight: 500;
  color: var(--text-secondary);
  border-radius: 6px;
  transition: all var(--transition);
}

.resources-grid li a:hover { background: var(--border-light); color: var(--text-primary); }

/* ===== HERO BANNER ===== */
.hero {
  background: linear-gradient(135deg, #0a0a0a 0%, #1a1a2e 50%, #0a0a0a 100%);
  padding: 72px 0 64px;
  text-align: center;
  position: relative;
  overflow: hidden;
}

.hero::before {
  content: '';
  position: absolute;
  top: -50%;
  left: -20%;
  width: 60%;
  height: 200%;
  background: radial-gradient(ellipse, rgba(0,114,245,0.12) 0%, transparent 70%);
  pointer-events: none;
}

.hero::after {
  content: '';
  position: absolute;
  top: -50%;
  right: -20%;
  width: 60%;
  height: 200%;
  background: radial-gradient(ellipse, rgba(0,114,245,0.08) 0%, transparent 70%);
  pointer-events: none;
}

.hero h1 {
  font-size: 48px;
  font-weight: 800;
  color: #fff;
  margin-bottom: 16px;
  position: relative;
  letter-spacing: -0.02em;
}

.hero p {
  font-size: 18px;
  color: rgba(255,255,255,0.6);
  max-width: 560px;
  margin: 0 auto;
  position: relative;
  line-height: 1.6;
}

/* ===== FILTERS ===== */
.filters-section {
  padding: 32px 0 0;
  border-bottom: 1px solid var(--border);
  background: var(--bg-white);
}

.filters-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  flex-wrap: wrap;
  padding-bottom: 20px;
}

.category-pills {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
  align-items: center;
}

.pill {
  padding: 7px 16px;
  font-size: 13px;
  font-weight: 500;
  color: var(--text-secondary);
  background: var(--bg);
  border: 1px solid var(--border);
  border-radius: var(--radius-pill);
  transition: all var(--transition);
  white-space: nowrap;
}

.pill:hover { border-color: var(--text-muted); color: var(--text-primary); }

.pill.active {
  background: var(--primary);
  color: #fff;
  border-color: var(--primary);
}

.search-box {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 8px 14px;
  background: var(--bg);
  border: 1px solid var(--border);
  border-radius: var(--radius-pill);
  min-width: 220px;
  transition: border-color var(--transition);
}

.search-box:focus-within { border-color: var(--accent); }

.search-box i { color: var(--text-muted); font-size: 16px; }

.search-box input {
  border: none;
  background: none;
  outline: none;
  font-size: 13px;
  font-family: inherit;
  color: var(--text-primary);
  width: 100%;
}

.search-box input::placeholder { color: var(--text-muted); }

/* ===== FEATURED ARTICLES ===== */
.featured-section { padding: 48px 0 32px; }

.section-label {
  font-size: 12px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--text-muted);
  margin-bottom: 24px;
}

.featured-grid {
  display: grid;
  grid-template-columns: 1fr 1fr 1fr;
  gap: 20px;
}

.featured-card {
  background: var(--bg-white);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  overflow: hidden;
  transition: all var(--transition);
  position: relative;
  display: flex;
  flex-direction: column;
}

.featured-card:hover {
  box-shadow: var(--card-shadow-hover);
  transform: translateY(-2px);
  border-color: transparent;
}

.featured-card-visual {
  height: 180px;
  position: relative;
  overflow: hidden;
}

.featured-card:nth-child(1) .featured-card-visual {
  background: linear-gradient(135deg, #0a0a0a, #1a1a3e);
}

.featured-card:nth-child(2) .featured-card-visual {
  background: linear-gradient(135deg, #0d1b2a, #1b3a5c);
}

.featured-card:nth-child(3) .featured-card-visual {
  background: linear-gradient(135deg, #1a1a2e, #2d1b3e);
}

.featured-card-visual .visual-icon {
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  font-size: 48px;
  color: rgba(0,114,245,0.5);
}

.featured-card:nth-child(1) .visual-icon::after {
  content: '';
  position: absolute;
  width: 120px;
  height: 120px;
  background: radial-gradient(circle, rgba(0,114,245,0.15) 0%, transparent 70%);
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
}

/* Stats overlay on featured card 1 */
.stats-overlay {
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  padding: 16px;
  background: linear-gradient(to top, rgba(0,0,0,0.7), transparent);
  display: flex;
  gap: 16px;
  justify-content: center;
}

.stat-item {
  text-align: center;
}

.stat-value {
  font-size: 18px;
  font-weight: 700;
  color: #fff;
}

.stat-label {
  font-size: 10px;
  color: rgba(255,255,255,0.7);
  text-transform: uppercase;
  letter-spacing: 0.04em;
}

.featured-card-body {
  padding: 20px;
  flex: 1;
  display: flex;
  flex-direction: column;
}

.featured-card .card-tag {
  display: inline-block;
  font-size: 11px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  color: var(--accent);
  margin-bottom: 8px;
}

.featured-card .card-title {
  font-size: 18px;
  font-weight: 700;
  line-height: 1.3;
  color: var(--text-primary);
  margin-bottom: 8px;
  letter-spacing: -0.01em;
}

.featured-card .card-excerpt {
  font-size: 14px;
  color: var(--text-secondary);
  line-height: 1.6;
  flex: 1;
  display: -webkit-box;
  -webkit-line-clamp: 3;
  -webkit-box-orient: vertical;
  overflow: hidden;
}

.featured-card .card-meta {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-top: 16px;
  padding-top: 16px;
  border-top: 1px solid var(--border-light);
}

.card-avatar {
  width: 32px;
  height: 32px;
  border-radius: 50%;
  background: linear-gradient(135deg, var(--accent), #6366f1);
  display: flex;
  align-items: center;
  justify-content: center;
  color: #fff;
  font-size: 12px;
  font-weight: 600;
  flex-shrink: 0;
}

.card-meta-text {
  display: flex;
  flex-direction: column;
}

.card-author {
  font-size: 13px;
  font-weight: 600;
  color: var(--text-primary);
}

.card-date {
  font-size: 12px;
  color: var(--text-muted);
}

/* ===== LATEST NEWS ===== */
.latest-section { padding: 16px 0 48px; }

.news-grid {
  display: grid;
  grid-template-columns: 1fr 1fr 1fr;
  gap: 20px;
}

.news-card {
  background: var(--bg-white);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 20px;
  transition: all var(--transition);
  display: flex;
  flex-direction: column;
}

.news-card:hover {
  box-shadow: var(--card-shadow-hover);
  transform: translateY(-2px);
  border-color: transparent;
}

.news-card .card-category {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  font-size: 11px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  color: var(--accent);
  background: rgba(0,114,245,0.08);
  padding: 3px 10px;
  border-radius: var(--radius-pill);
  margin-bottom: 12px;
  width: fit-content;
}

.news-card .card-title {
  font-size: 16px;
  font-weight: 700;
  line-height: 1.35;
  color: var(--text-primary);
  margin-bottom: 8px;
  letter-spacing: -0.01em;
}

.news-card .card-excerpt {
  font-size: 13px;
  color: var(--text-secondary);
  line-height: 1.6;
  flex: 1;
  display: -webkit-box;
  -webkit-line-clamp: 3;
  -webkit-box-orient: vertical;
  overflow: hidden;
  margin-bottom: 16px;
}

.news-card .card-meta {
  display: flex;
  align-items: center;
  gap: 10px;
  padding-top: 12px;
  border-top: 1px solid var(--border-light);
}

.news-card .card-avatar {
  width: 28px;
  height: 28px;
  font-size: 10px;
}

.show-more-wrap {
  display: flex;
  justify-content: center;
  margin-top: 36px;
}

.btn-show-more {
  padding: 12px 32px;
  font-size: 14px;
  font-weight: 600;
  color: var(--text-primary);
  background: var(--bg-white);
  border: 1px solid var(--border);
  border-radius: var(--radius-pill);
  transition: all var(--transition);
  display: flex;
  align-items: center;
  gap: 8px;
}

.btn-show-more:hover {
  border-color: var(--text-muted);
  box-shadow: var(--card-shadow);
}

.btn-show-more.loading { pointer-events: none; opacity: 0.6; }

/* No results */
.no-results {
  text-align: center;
  padding: 64px 24px;
  display: none;
}

.no-results i { font-size: 48px; color: var(--border); margin-bottom: 16px; }

.no-results h3 {
  font-size: 18px;
  font-weight: 600;
  color: var(--text-primary);
  margin-bottom: 8px;
}

.no-results p { font-size: 14px; color: var(--text-muted); max-width: 400px; margin: 0 auto; }

/* ===== CTA BANNER ===== */
.cta-section {
  padding: 80px 0;
  background: linear-gradient(135deg, #0a0a0a, #1a1a2e);
  position: relative;
  overflow: hidden;
}

.cta-section::before {
  content: '';
  position: absolute;
  top: 0; left: 0; right: 0; bottom: 0;
  background: radial-gradient(ellipse at 30% 50%, rgba(0,114,245,0.1) 0%, transparent 60%);
  pointer-events: none;
}

.cta-content {
  text-align: center;
  position: relative;
}

.cta-content h2 {
  font-size: 36px;
  font-weight: 800;
  color: #fff;
  margin-bottom: 12px;
  letter-spacing: -0.02em;
}

.cta-content h2 em {
  font-style: normal;
  color: var(--accent);
}

.cta-content p {
  font-size: 16px;
  color: rgba(255,255,255,0.55);
  margin-bottom: 32px;
  max-width: 520px;
  margin-left: auto;
  margin-right: auto;
  line-height: 1.6;
}

.cta-buttons { display: flex; gap: 12px; justify-content: center; margin-bottom: 48px; }

.btn-primary {
  padding: 12px 28px;
  font-size: 14px;
  font-weight: 600;
  color: #fff;
  background: var(--accent);
  border-radius: var(--radius-pill);
  transition: all var(--transition);
  display: inline-flex;
  align-items: center;
  gap: 8px;
}

.btn-primary:hover { background: var(--accent-hover); }

.btn-secondary {
  padding: 12px 28px;
  font-size: 14px;
  font-weight: 600;
  color: rgba(255,255,255,0.8);
  background: rgba(255,255,255,0.08);
  border: 1px solid rgba(255,255,255,0.15);
  border-radius: var(--radius-pill);
  transition: all var(--transition);
  display: inline-flex;
  align-items: center;
  gap: 8px;
}

.btn-secondary:hover { background: rgba(255,255,255,0.14); color: #fff; }

.enterprise-block {
  background: rgba(255,255,255,0.04);
  border: 1px solid rgba(255,255,255,0.08);
  border-radius: var(--radius);
  padding: 32px 40px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  max-width: 640px;
  margin: 0 auto;
  gap: 24px;
}

.enterprise-block p {
  margin: 0;
  text-align: left;
  font-size: 14px;
  color: rgba(255,255,255,0.6);
}

.btn-explore-enterprise {
  padding: 10px 24px;
  font-size: 13px;
  font-weight: 600;
  color: #fff;
  background: rgba(255,255,255,0.1);
  border: 1px solid rgba(255,255,255,0.2);
  border-radius: var(--radius-pill);
  transition: all var(--transition);
  white-space: nowrap;
}

.btn-explore-enterprise:hover { background: rgba(255,255,255,0.18); }

/* ===== FOOTER ===== */
.footer {
  background: var(--primary);
  padding: 64px 0 32px;
  color: rgba(255,255,255,0.6);
}

.footer-grid {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 32px;
  margin-bottom: 48px;
}

.footer-col h5 {
  font-size: 12px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: rgba(255,255,255,0.4);
  margin-bottom: 16px;
}

.footer-col ul { list-style: none; }

.footer-col li { margin-bottom: 8px; }

.footer-col a {
  font-size: 13px;
  color: rgba(255,255,255,0.55);
  transition: color var(--transition);
}

.footer-col a:hover { color: #fff; }

.footer-bottom {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding-top: 24px;
  border-top: 1px solid rgba(255,255,255,0.08);
}

.footer-bottom .status {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 13px;
  color: rgba(255,255,255,0.4);
}

.status-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: #22c55e;
}

.footer-social {
  display: flex;
  gap: 16px;
}

.footer-social a {
  font-size: 18px;
  color: rgba(255,255,255,0.35);
  transition: color var(--transition);
}

.footer-social a:hover { color: #fff; }

/* ===== RESPONSIVE ===== */
@media (max-width: 1024px) {
  .featured-grid { grid-template-columns: 1fr 1fr; }
  .news-grid { grid-template-columns: 1fr 1fr; }
  .footer-grid { grid-template-columns: repeat(3, 1fr); }
  .mega-menu { min-width: 500px; }
}

@media (max-width: 768px) {
  .hero h1 { font-size: 32px; }
  .hero p { font-size: 16px; }
  .featured-grid { grid-template-columns: 1fr; }
  .news-grid { grid-template-columns: 1fr; }
  .footer-grid { grid-template-columns: repeat(2, 1fr); }
  .filters-row { flex-direction: column; align-items: stretch; }
  .search-box { min-width: auto; }
  .nav-links { display: none; }
  .enterprise-block { flex-direction: column; text-align: center; }
