let activeCategory = 'all';
let searchQuery = '';
let visibleCount = 8;

// ===== RENDER =====
function renderPosts() {
  const grid = document.getElementById('newsGrid');
  const noResults = document.getElementById('noResults');
  const showMoreWrap = document.getElementById('showMoreWrap');

  let filtered = allPosts.slice(0, visibleCount);

  // Category filter
  if (activeCategory !== 'all') {
    filtered = filtered.filter(p => p.category === activeCategory);
  }

  // Search filter
  if (searchQuery) {
    const q = searchQuery.toLowerCase();
    filtered = filtered.filter(p =>
      p.title.toLowerCase().includes(q) ||
      p.excerpt.toLowerCase().includes(q) ||
      p.author.toLowerCase().includes(q) ||
      p.category.toLowerCase().includes(q)
    );
  }

  if (filtered.length === 0) {
    grid.innerHTML = '';
    noResults.style.display = 'block';
    showMoreWrap.style.display = 'none';
  } else {
    noResults.style.display = 'none';
    grid.innerHTML = filtered.map(post => `
      <article class="news-card" data-category="${post.category}">
        <span class="card-category"><i class="ri-folder-3-line"></i> ${post.category}</span>
        <h3 class="card-title">${post.title}</h3>
        <p class="card-excerpt">${post.excerpt}</p>
        <div class="card-meta">
          <div class="card-avatar">${post.initials}</div>
          <div class="card-meta-text">
            <span class="card-author">${post.author}</span>
            <span class="card-date">${post.date}</span>
          </div>
        </div>
      </article>
    `).join('');

    // Show/hide "show more" button
    const totalFiltered = activeCategory === 'all'
      ? allPosts.length
      : allPosts.filter(p => p.category === activeCategory).length;

    showMoreWrap.style.display = visibleCount >= totalFiltered ? 'none' : 'flex';
  }

  // Also filter featured cards
  filterFeatured();
}

function filterFeatured() {
  const cards = document.querySelectorAll('#featuredGrid .featured-card');
  let anyVisible = false;

  cards.forEach(card => {
    const categories = card.dataset.categories || '';
    const searchable = (card.dataset.searchable || '').toLowerCase();
    let show = true;

    if (activeCategory !== 'all') {
      show = categories.includes(activeCategory);
    }

    if (searchQuery && show) {
      const q = searchQuery.toLowerCase();
      show = searchable.includes(q) ||
             card.querySelector('.card-title').textContent.toLowerCase().includes(q) ||
             card.querySelector('.card-excerpt').textContent.toLowerCase().includes(q);
    }

    card.style.display = show ? '' : 'none';
    if (show) anyVisible = true;
  });

  const featuredSection = document.getElementById('featuredSection');
  featuredSection.style.display = anyVisible ? '' : 'none';
}

// ===== INTERACTIONS =====
function filterCategory(category, el) {
  activeCategory = category;

  document.querySelectorAll('#categoryPills .pill').forEach(p => p.classList.remove('active'));
  el.classList.add('active');

  renderPosts();
}

function handleSearch() {
  searchQuery = document.getElementById('searchInput').value.trim();
  renderPosts();
}

function showMore() {
  const btn = document.getElementById('showMoreBtn');
  btn.classList.add('loading');
  btn.innerHTML = '<i class="ri-loader-4-line ri-spin"></i> Loading...';

  setTimeout(() => {
    visibleCount += 8;
    btn.classList.remove('loading');
    btn.innerHTML = '<i class="ri-arrow-down-line"></i> Show more posts';
    renderPosts();
  }, 400);
}

