function toggleDropdown(which) {
  const productsBtn = document.getElementById('productsBtn');
  const resourcesBtn = document.getElementById('resourcesBtn');

  if (which === 'products') {
    const isOpen = productsBtn.classList.contains('active');
    productsBtn.classList.remove('active');
    resourcesBtn.classList.remove('active');
    if (!isOpen) productsBtn.classList.add('active');
  } else {
    const isOpen = resourcesBtn.classList.contains('active');
    productsBtn.classList.remove('active');
    resourcesBtn.classList.remove('active');
    if (!isOpen) resourcesBtn.classList.add('active');
  }
}

// Close dropdowns on outside click
document.addEventListener('click', (e) => {
  const productsBtn = document.getElementById('productsBtn');
  const resourcesBtn = document.getElementById('resourcesBtn');

  if (!productsBtn.contains(e.target)) {
    productsBtn.classList.remove('active');
  }
  if (!resourcesBtn.contains(e.target)) {
    resourcesBtn.classList.remove('active');
  }
});

// ===== MOBILE NAV =====
function toggleMobileNav() {
  const nav = document.querySelector('.nav-links');
  nav.style.display = nav.style.display === 'flex' ? 'none' : 'flex';
  nav.style.flexDirection = 'column';
  nav.style.position = 'absolute';
  nav.style.top = '64px';
  nav.style.left = '0';
  nav.style.right = '0';
  nav.style.background = '#fff';
  nav.style.padding = '16px';
  nav.style.borderBottom = '1px solid var(--border)';
  nav.style.zIndex = '99';
}

// ===== INIT =====
renderPosts();
</script>
